  // Prestige-newspaper data graphic (FT / NYT / Economist register).
  const BG = '#FFF1E5', INK = '#33302E', MUTED = '#66605C', GRID = 'rgba(51,48,46,0.16)';
  const HI = '#990F3D', GREY = '#A79E95';

