    c.strokeStyle = 'rgba(30,28,25,0.25)'; c.lineWidth = 0.7; for (let i = -6; i < 7; i++) { c.beginPath(); c.moveTo(i * 40, -h); c.lineTo(i * 40 + 30, h); c.stroke(); }
