  const S = { block: 0.1, photo: 0.35, tapeA: 0.7, tapeB: 0.8, clip: 0.95, tapeC: 1.3, map: 1.45, pin: 1.7, t1: 1.85, t2: 2.1, hl1: [2.4, 2.85], hl2: [2.95, 3.35], ring: [3.45, 3.95] };
