  })();
  const KNOBS = [-100, -34, 34, 100];
  const drawNet = (c, t, tq) => {
    const back = H.clamp((tq - X.back[0]) / (X.back[1] - X.back[0])), tune = H.clamp((tq - X.tune[0]) / (X.tune[1] - X.tune[0]));
